import {STAGES,uid,day,classify,conflicts,alternatives,safeURL,calendarFile,validateProfile,profileImport,briefFor,seed,triage} from './engine.mjs';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',inbox:'M3 4h18v16H3z M3 14h5l2 3h4l2-3h5',briefcase:'M3 7h18v14H3z M8 7V3h8v4 M3 12c5 4 13 4 18 0 M10 13h4',calendar:'M3 5h18v16H3z M7 3v4 M17 3v4 M3 10h18 M8 14h2 M14 14h2 M8 17h2',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z',check:'m5 12 4 4L19 6',shield:'M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6z m-4 9 3 3 5-6',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v5l3 2',settings:'M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z M12 9a3 3 0 1 0 0 6 3 3 0 0 0 0-6',user:'M12 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M4 21v-2a8 6 0 0 1 16 0v2',arrow:'M5 12h14 m-5-5 5 5-5 5',plus:'M12 5v14 M5 12h14',chevron:'m9 5 7 7-7 7',download:'M12 3v12 m-5-5 5 5 5-5 M4 17v4h16v-4',refresh:'M20 8a8 8 0 1 0 0 8 M20 3v5h-5',bell:'M6 16V9a6 6 0 0 1 12 0v7l2 2H4z M10 21h4',mail:'M3 5h18v14H3z m0 0 9 8 9-8',link:'m10 14 4-4 M8 16l-1 1a4 4 0 0 1-6-6l4-4a4 4 0 0 1 6 0 M16 8l1-1a4 4 0 0 1 6 6l-4 4a4 4 0 0 1-6 0',book:'M3 3h7l2 2 2-2h7v17h-7l-2 2-2-2H3z M12 5v17',menu:'M4 6h16 M4 12h16 M4 18h16',location:'M12 22s8-8 8-13A8 8 0 0 0 4 9c0 5 8 13 8 13 M12 7a2 2 0 1 0 0 4 2 2 0 0 0 0-4',bolt:'m13 2-9 12h7l-1 8 10-13h-8z',external:'M14 3h7v7 M21 3 10 14 M10 3H3v18h18v-7',trash:'M4 6h16 M8 6V3h8v3 M6 6l1 15h10l1-15 M10 10v7 M14 10v7'};
const icon=(name,cls='')=>`<svg class="${cls}" aria-hidden="true" viewBox="0 0 24 24"><path d="${paths[name]||paths.spark}"/></svg>`;
const btn=(label,action,style='',ico='',attrs='')=>`<button class="btn ${style}" data-action="${action}" ${attrs}>${ico?icon(ico):''}${label}</button>`;
const empty=(text,action='',label='')=>`<div class="empty">${icon('spark')}${text}${action?`<div style="margin-top:15px">${btn(label,action,'primary')}</div>`:''}</div>`;
const badge=(text,cls='')=>`<span class="badge ${cls}">${esc(text)}</span>`;
const initials=s=>(s||'?').split(/\s+/).map(x=>x[0]).slice(0,2).join('').toUpperCase();
const dt=(s,opt={})=>new Date(s).toLocaleDateString(undefined,{month:'short',day:'numeric',...opt});
const tm=s=>new Date(s).toLocaleTimeString(undefined,{hour:'numeric',minute:'2-digit'});
const full=s=>`${dt(s,{weekday:'short'})} · ${tm(s)}`;
const localInput=s=>{const d=new Date(s);return new Date(+d-d.getTimezoneOffset()*60000).toISOString().slice(0,16)};
const pending=()=>state.approvals.filter(a=>a.status==='pending');
const upcoming=()=>state.events.filter(e=>Date.parse(e.end)>Date.now()).sort((a,b)=>Date.parse(a.start)-Date.parse(b.start));
const appFor=id=>state.apps.find(a=>a.id===id);
if(!localStorage.getItem('aw-live-intro-v1')){localStorage.setItem('aw-mode-v1','workspace');localStorage.setItem('aw-live-intro-v1','1')}
let mode=localStorage.getItem('aw-mode-v1')||'workspace';let state=loadState();let view='overview',filter='All',search='',selectedApp=state.apps.find(a=>a.stage==='Interview')?.id||state.apps[0]?.id||'',backend=null;
function loadState(){try{const s=JSON.parse(localStorage.getItem('aw-'+mode+'-v1'));if(s?.version===1&&Array.isArray(s.apps))return s}catch{}return seed(mode==='demo')}
let gmailError='',gmailRetryAfter=0,gmailBusy=false;
let toastTimer;function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4600)}
function persist(){try{localStorage.setItem('aw-'+mode+'-v1',JSON.stringify(state))}catch{toast('Browser storage is full or unavailable. Export a backup before closing.')}}
function log(text,kind='local'){state.activity.unshift({id:uid(),at:new Date().toISOString(),text,kind});state.activity=state.activity.slice(0,1000)}
function save(message){persist();render();if(message)toast(message)}
function go(v){view=v;filter='All';search='';render();window.scrollTo(0,0);$('#main').focus({preventScroll:true})}
function switchMode(){mode=mode==='demo'?'workspace':'demo';localStorage.setItem('aw-mode-v1',mode);state=loadState();selectedApp=state.apps[0]?.id||'';view='overview';render();toast(mode==='workspace'?'Your workspace is ready. Add your profile to begin.':'Fictional demo loaded. Your workspace is kept separately.')}
function download(name,text,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
const navs=[['overview','Overview','grid'],['inbox','Inbox','inbox'],['applications','Applications','briefcase'],['calendar','Calendar','calendar'],['prep','Interview prep','spark'],['approvals','Approvals','shield'],['activity','Activity','clock'],['profile','About me','user'],['settings','Settings & connections','settings']];
function render(){document.title=`AUTO WORK · ${navs.find(n=>n[0]===view)?.[1]||'Overview'}`;const n=state.profile.name||'Your workspace';$('#app').innerHTML=`<div class="shell"><aside class="sidebar" aria-label="Main navigation"><a href="#" class="brand" data-action="nav" data-view="overview"><span class="mark">${icon('bolt')}</span>AUTO WORK<span style="font-size:9px;letter-spacing:0;align-self:flex-start;margin-top:5px;color:#879779">β</span></a><div class="nav-label">YOUR COMMAND CENTER</div><nav class="nav">${navs.slice(0,7).map(navItem).join('')}</nav><div class="nav-label" style="margin-top:30px">PERSONALIZE</div><nav class="nav">${navs.slice(7).map(navItem).join('')}</nav><div class="side-bottom"><div class="safety-card">${icon('shield')}<strong>You’re always in control.</strong><p>Review the important things. Every action has a history.</p></div><button class="side-profile" data-action="nav" data-view="profile"><span class="avatar">${state.profile.name?esc(initials(state.profile.name)):icon('user')}</span><span><strong>${esc(n)}</strong><small>${esc(state.profile.education||'Personal career assistant')}</small></span>${icon('chevron')}</button></div></aside><div class="content"><header class="topbar"><button class="mobile-menu icon-button" aria-label="Open navigation" data-action="menu">${icon('menu')}</button><div class="crumb">Workspace<span>/</span><b>${navs.find(n=>n[0]===view)?.[1]}</b></div><div class="top-actions">${badge(mode==='demo'?'Demo workspace':'Personal workspace',mode==='demo'?'amber dot':'green dot')}<button class="icon-button" aria-label="View reminders" data-action="reminders">${icon('bell')}</button><button class="avatar" aria-label="Edit your profile" data-action="nav" data-view="profile">${state.profile.name?esc(initials(state.profile.name)):icon('user')}</button></div></header><main class="main" id="main" tabindex="-1">${({overview,inbox,applications,calendar,prep,approvals,activity,profile,settings}[view]||overview)()}<footer class="footer-note"><span>A little less busywork. A little more possibility.</span><span>AUTO WORK · All changes stay local · ${new Intl.DateTimeFormat().resolvedOptions().timeZone}</span></footer></main></div></div>`}
function navItem([id,label,ico]){let count=id==='approvals'?pending().length:id==='inbox'?state.messages.filter(m=>!m.processed).length:0;return `<button data-action="nav" data-view="${id}" class="${view===id?'active':''}" ${view===id?'aria-current="page"':''}>${icon(ico)}${label}${count?`<span class="count">${count}</span>`:''}</button>`}
function heading(title,sub,buttons='',eyebrow='YOUR CAREER, IN MOTION'){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${esc(title)}</h1><p class="subtitle">${sub}</p></div><div class="button-row">${buttons}</div></div>`}
function demoStrip(){return mode==='demo'?`<div class="demo-strip"><span>${icon('spark')} <b>FICTIONAL DEMO — no real interviews.</b> All companies, messages and events here are fictional.</span><button data-action="switch-mode">Start my workspace ${icon('arrow')}</button></div>`:`<div class="demo-strip"><span>${icon('shield')} <b>Local workspace.</b> Data is saved in this browser. Email sending and calendar writes are unavailable.</span><button data-action="export">Back up data ${icon('download')}</button></div>`}
function overview(){let a=state.apps.find(a=>a.stage==='Interview'),ev=upcoming().find(e=>e.type==='Interview'),r=state.reminders.filter(r=>!r.done).sort((a,b)=>Date.parse(a.due)-Date.parse(b.due));const greeting=new Date().getHours()<12?'Good morning':new Date().getHours()<18?'Good afternoon':'Good evening';return heading(`${greeting}${state.profile.name?', '+state.profile.name.split(' ')[0]:''}.`,'Your next chapter is taking shape. Let’s keep things moving.',btn('Run inbox triage','triage','','refresh')+btn('Add application','add-app','primary','plus'),dt(new Date(),{weekday:'long',year:'numeric'}))+demoStrip()+`<div class="stats">${[['briefcase','Active applications',state.apps.filter(a=>!['Closed','Saved'].includes(a.stage)).length,'Your pipeline'],['calendar','Upcoming interviews',upcoming().filter(e=>e.type==='Interview').length,'On the horizon'],['shield','Awaiting your review',pending().length,'You decide'],['check','Open reminders',r.length,'One step at a time']].map(([ic,l,n,note])=>`<div class="stat"><div class="stat-icon">${icon(ic)}</div><div><small>${l}</small><div class="stat-num">${String(n).padStart(2,'0')}</div></div><span class="stat-note">${note}</span></div>`).join('')}</div><div class="dashboard-grid"><div class="stack"><section class="hero">${badge(mode==='demo'?'FICTIONAL DEMO':a?'YOUR NEXT OPPORTUNITY':'MAKE ROOM FOR WHAT’S NEXT','')}<div class="eyebrow">${icon('spark')} THE NEXT BIG THING</div><h2>${a?esc(a.company):'A little preparation. A lot of possibility.'}</h2><p>${a?esc(a.role):'Keep your applications, interviews and next steps in one place.'}</p><div class="hero-info"><span>${icon('calendar')}${ev?full(ev.start):'Your schedule, at a glance'}</span><span>${icon('shield')}Preparation under your control</span></div>${btn(a?'Open interview brief':state.profile.name?'Explore my applications':'Set up my profile',a?'hero-prep':state.profile.name?'applications-nav':'profile-nav','lime','spark',a?`data-id="${a.id}"`:'')}${btn('View calendar','calendar-nav','subtle','arrow')}</section><section class="card"><div class="card-header"><h2>Your assistant’s workflow</h2>${badge('Local rules','green dot')}</div><div class="workflow">${[['inbox','Triage inbox','Find the signal'],['calendar','Check schedule','Spot conflicts'],['spark','Prepare together','Build your brief'],['shield','Your approval','Nothing sent']].map(([i,t,s])=>`<div class="flow-step"><div class="flow-icon">${icon(i)}</div><b>${t}</b><small>${s}</small></div>`).join('')}</div></section><section class="card"><div class="card-header"><h2>Inbox, with the noise turned down</h2>${btn('View inbox','inbox-nav','subtle','arrow')}</div>${state.messages.length?state.messages.slice(0,3).map(messageRow).join(''):empty('Import a message to find interview invitations.','import-message','Import a message')}</section><div class="approval-callout">${icon('shield')}<div><h3>${pending().length?`${pending().length} ${pending().length===1?'thing needs':'things need'} your green light`:'You’re all caught up'}</h3><p>${pending().length?'Review drafts and scheduling plans when you’re ready.':'Future drafts and plans will appear here.'}</p></div>${btn('Review queue','approvals-nav','','arrow')}</div></div><div class="stack"><section class="card"><div class="card-header"><h2>Ahead of you</h2>${btn('Calendar','calendar-nav','subtle','arrow')}</div><p class="tiny" style="margin-top:-8px">${dt(new Date(),{month:'long',year:'numeric'})}</p><div class="calendar-mini">${Array.from({length:7},(_,i)=>{let d=new Date(day(i));return `<div class="date-pill ${i===1?'selected':''}"><small>${d.toLocaleDateString(undefined,{weekday:'short'})}</small><b>${d.getDate()}</b></div>`}).join('')}</div>${upcoming().slice(0,3).map(e=>`<div class="timeline-item"><span class="timeline-time">${dt(e.start)}<br>${tm(e.start)}</span><div class="timeline-line"><b>${esc(e.title)}</b><p>${Math.round((Date.parse(e.end)-Date.parse(e.start))/60000)} min · ${esc(e.type)}</p></div></div>`).join('')||empty('Your schedule has room for what’s next.','add-event','Add a busy block')}</section><section class="card"><div class="card-header"><h2>Small steps, big moves</h2>${btn('Add','add-reminder','subtle','plus')}</div>${r.slice(0,4).map(reminderRow).join('')||empty('No open reminders. You’re all set.')}</section>${!state.profile.name?`<section class="card" style="background:#edf2e3"><div class="eyebrow">A BETTER FIT STARTS WITH YOU</div><h2 style="margin-bottom:10px">Make it personal.</h2><p class="subtitle">Save your experience, strengths and goals. Your preparation should sound like you.</p><div style="margin-top:15px">${btn('Tell me about you','profile-nav','','arrow')}</div></section>`:`<section class="card"><div class="eyebrow">YOUR NORTH STAR</div><h2>${esc(state.profile.target||'Your next opportunity')}</h2><p class="subtitle" style="margin-top:10px">${esc(state.profile.education)}</p>${btn('Update my goals','profile-nav','subtle','arrow')}</section>`}</div></div>`}
function messageRow(m){let a=appFor(m.appId);return `<button class="message-row" data-action="message" data-id="${esc(m.id)}"><span class="company-logo ${a?.color||'green'}">${esc(initials(a?.company||m.from))}</span><span class="row-copy"><b>${esc(m.from)}</b><p>${esc(m.subject)}</p></span><span class="row-end">${badge(m.category||'Unprocessed',m.category==='Interview'?'purple':m.category==='Offer'?'green':'')}<span class="tiny">${dt(m.received)}</span></span></button>`}
function reminderRow(r){return `<div class="reminder"><button class="check ${r.done?'done':''}" data-action="complete-reminder" data-id="${r.id}" aria-label="${r.done?'Reopen':'Complete'} reminder">${r.done?icon('check'):''}</button><div style="flex:1"><p style="${r.done?'text-decoration:line-through':''}">${esc(r.title)}</p><small class="${Date.parse(r.due)<Date.now()&&!r.done?'due':''}">${full(r.due)}${r.done?' · Completed':''}</small></div>${!r.done?`<button class="tiny" data-action="snooze" data-id="${r.id}" title="Snooze by one hour">+1h</button>`:''}</div>`}
function inbox(){let messages=state.messages.filter(m=>(filter==='All'||(m.category||'Unprocessed')===filter)&&`${m.subject} ${m.from} ${m.body}`.toLowerCase().includes(search.toLowerCase()));return heading('A clearer inbox.','Spot interview invitations, track replies, and decide what happens next.',btn(gmailBusy?'Refreshing…':'Refresh Gmail','sync-gmail','','refresh',gmailBusy?'disabled':'')+btn('Import message','import-message','','plus')+btn('Run triage','triage','primary','refresh'))+demoStrip()+`${state.lastGmailSync?`<p class="tiny">Last Gmail refresh: ${full(state.lastGmailSync)} · up to 20 matching messages from the past 30 days. ${gmailError?'Saved results may be stale after the latest failed refresh.':''}</p>`:''}${gmailError?`<div class="notice amber">${esc(gmailError)} Previous messages are retained.</div>`:''}<div class="tabs">${['All','Interview','Application','Offer','Update','Other','Unprocessed'].map(t=>`<button class="tab ${filter===t?'active':''}" data-action="filter" data-filter="${t}">${t}</button>`).join('')}<input class="search" style="margin-left:auto" id="inbox-search" aria-label="Search inbox" placeholder="Search messages…" value="${esc(search)}"></div><section class="card">${messages.map(messageRow).join('')||empty('No messages in this view.','import-message','Import a message')}</section><div class="notice">${icon('shield')} Triage uses transparent keyword rules. It can miss invitations or flag the wrong message. Dates are never silently inferred, and drafts never send themselves.</div>`}
function applications(){return heading('Every opportunity, in view.','From that first “what if” to your next offer. Click a card to update its details.',btn('Load existing tracker','load-tracker','','link')+btn('Import jobs JSON','import-jobs','','download')+btn('Add application','add-app','primary','plus'))+demoStrip()+`<div class="board">${STAGES.map(stage=>`<section class="board-col"><h3>${stage}<span class="muted">${state.apps.filter(a=>a.stage===stage).length}</span></h3>${state.apps.filter(a=>a.stage===stage).map(a=>`<article class="job-card" tabindex="0" role="button" data-action="edit-app" data-id="${a.id}" aria-label="Edit ${esc(a.company)} application"><div class="company-logo ${a.color||'green'}">${esc(initials(a.company))}</div><h3>${esc(a.company)}</h3><p>${esc(a.role)}</p><small>${a.deadline?'Follow up '+dt(a.deadline):'No follow-up date'}</small></article>`).join('')}${btn('Add','add-app','subtle','plus',`data-stage="${stage}"`)}</section>`).join('')}</div><div class="notice">Your tracker is local. Stage changes and application notes do not submit or modify an application on an employer’s website.</div>`}
function calendar(){return heading('Make space for your next step.','Check conflicts before committing. All times use your browser’s time zone.',btn('Check a proposed time','schedule','','clock')+btn('Add busy block','add-event','primary','plus'))+demoStrip()+`<div class="two-col"><section class="card"><div class="card-header"><h2>Upcoming schedule</h2>${badge(new Intl.DateTimeFormat().resolvedOptions().timeZone)}</div>${upcoming().map(e=>`<div class="event-card"><div class="event-date"><small>${new Date(e.start).toLocaleDateString(undefined,{month:'short'})}</small><b>${new Date(e.start).getDate()}</b></div><div class="event-info"><h3>${esc(e.title)}</h3><p>${full(e.start)} – ${tm(e.end)}</p>${badge(e.type,e.type==='Interview'?'purple':'')}</div><div class="button-row">${btn('Export .ics','export-event','','download',`data-id="${e.id}"`)}<button class="tiny" data-action="delete-event" data-id="${e.id}" aria-label="Delete local event">${icon('trash')}</button></div></div>`).join('')||empty('No upcoming events. Add your commitments before checking availability.','add-event','Add a busy block')}</section><div class="stack"><section class="card"><h2>Availability you can trust</h2><div class="notice">Checks include only events in this workspace. Import Google Calendar or add your busy blocks for a useful conflict check.</div><div class="toggle-row"><div><h3>Buffer around events</h3><p>Protect time before and after each meeting.</p></div>${badge(state.settings.buffer+' min','green')}</div><div class="toggle-row"><div><h3>External calendar changes</h3><p>Unavailable. Approved plans can be exported manually.</p></div>${icon('shield')}</div>${btn('Connection settings','settings-nav','subtle','arrow')}</section><section class="card"><div class="card-header"><h2>Your reminders</h2>${btn('Add','add-reminder','subtle','plus')}</div>${state.reminders.map(reminderRow).join('')||empty('No reminders yet.')}</section></div></div>`}
function prep(){const a=appFor(selectedApp)||state.apps[0];if(!a)return heading('Walk in feeling ready.','Company context, practice questions and your story, in one place.')+empty('Add an application to start your preparation.','add-app','Add application');selectedApp=a.id;const b=briefFor(a,state.profile,state.sources);return heading('Walk in feeling ready.','Your experience. Their opportunity. A little preparation to connect the two.',btn('Export brief','export-brief','','download')+btn('Add research source','add-source','primary','plus'))+`<div class="profile-banner"><span class="company-logo ${a.color||'peach'}">${esc(initials(a.company))}</span><div><h2>${esc(a.company)}</h2><p>${esc(a.role)}</p></div><select class="interview-selector" id="prep-app" aria-label="Choose application" style="margin-left:auto">${state.apps.map(x=>`<option value="${x.id}" ${a.id===x.id?'selected':''}>${esc(x.company)} · ${esc(x.role)}</option>`).join('')}</select></div><div class="notice amber">${icon('book')} <b>Template preparation, not live AI research.</b> Questions below are practice suggestions, not a prediction of the employer’s process. Company facts appear only when you add a source. ${mode==='demo'?'This company is fictional.':''}</div><div class="dashboard-grid"><section class="card"><div class="card-header"><h2>Your interview brief</h2>${badge('Personalized from saved profile','green')}</div><div class="prep-section" style="border-top:0;padding-top:4px"><h3>A starting point for “tell me about yourself”</h3><p class="body-text">${esc(b.intro)}</p>${!state.profile.name||!state.profile.about?btn('Complete my profile','profile-nav','subtle','arrow'):''}</div><div class="prep-section"><h3>What this role calls for</h3><p class="body-text">${esc(a.description||'Add the job description in Applications to ground your preparation.')}</p><div class="chip-row">${b.matched.map(s=>badge(s,'green')).join('')}</div><p class="tiny">${b.matched.length?'Exact keyword matches from your saved skills. Confirm the level of experience needed.':'No exact skill matches yet. Add your skills and the job description; no qualifications are assumed.'}</p></div><div class="prep-section"><h3>Stories only you can tell</h3><p class="body-text">${esc(b.experience||'Your projects and experience will appear here once you save them in About me.')}</p><p class="tiny">${esc(b.missing)} Structure each story: situation → task → action → result. Use only results you can support.</p></div><div class="prep-section"><h3>Practice these out loud</h3><ol>${b.questions.map(q=>`<li>${esc(q)}</li>`).join('')}</ol></div><div class="prep-section"><h3>Good questions to bring</h3><ul>${b.ask.map(q=>`<li>${esc(q)}</li>`).join('')}</ul></div><label class="field"><span>Your practice notes</span><textarea id="prep-notes" rows="5" placeholder="Your STAR stories, questions, or things to revisit…">${esc(state.notes[a.id]||'')}</textarea></label>${btn('Save practice notes','save-prep','primary','check')}</section><div class="stack"><section class="card"><div class="card-header"><h2>Company research</h2>${badge(b.sources.length+' sources')}</div>${b.sources.length?b.sources.map(s=>`<div class="source"><a class="inline-link" href="${esc(safeURL(s.url))}" target="_blank" rel="noopener noreferrer"><b>${esc(s.title)}</b> ${icon('external')}</a><p>${esc(s.note)}</p>${badge(s.type==='Fact'?'User-entered fact · verify source':'Hypothesis · unverified',s.type==='Fact'?'green':'amber')}<p class="tiny">Added ${dt(s.added)} · Check the source’s publication date.</p><button class="tiny" data-action="delete-source" data-id="${s.id}">Remove source</button></div>`).join(''):empty('No company facts have been verified. Add a job posting, company page, or recent announcement.','add-source','Add a source')}<div class="notice">Source notes are written by you and aren’t independently verified. Keep facts and your own hypotheses separate.</div></section><section class="card"><h2>A thoughtful research checklist</h2>${['What does the company sell, and to whom?','Which campaign or product can you discuss specifically?','How does this role contribute to its marketing goals?','What has changed recently? Find a dated primary source.','What is still unknown? Ask the recruiter.'].map(t=>`<p class="tiny" style="margin:15px 0">${icon('chevron')} ${t}</p>`).join('')}</section></div></div>`}
function approvals(){const list=state.approvals.filter(a=>filter==='All'||a.status===filter.toLowerCase());return heading('Your judgment, at the center.','Review the wording, the details and the timing. You always have the final say.')+`<div class="notice">${icon('shield')} Approval marks a draft ready or adds a local calendar hold. It does not send email or write to Google Calendar. Export or copy approved items to carry them out yourself.</div><div class="tabs">${['All','Pending','Approved','Rejected'].map(t=>`<button class="tab ${filter===t?'active':''}" data-action="filter" data-filter="${t}">${t}</button>`).join('')}</div><div class="stack">${list.map(a=>`<section class="card"><div class="card-header"><div><div class="eyebrow">${a.type==='reply'?'EMAIL DRAFT':'SCHEDULING PLAN'} · ${dt(a.created)}</div><h2>${esc(a.title)}</h2></div>${badge(a.status,a.status==='pending'?'amber':a.status==='approved'?'green':'')}</div>${a.type==='schedule'?`<p class="body-text">${full(a.start)} – ${tm(a.end)}<br>${esc(a.checkSummary||'Recheck availability before exporting.')}</p>`:`<p class="body-text">${esc(a.body)}</p>`}<div class="button-row">${a.status==='pending'?btn('Review & edit','review-approval','primary','shield',`data-id="${a.id}"`):a.status==='approved'?btn(a.type==='reply'?'Copy draft':'Export .ics',a.type==='reply'?'copy-draft':'export-approval','','download',`data-id="${a.id}"`):''}${a.status==='pending'?btn('Reject','reject-approval','danger','',`data-id="${a.id}"`):''}</div></section>`).join('')||empty('Nothing in this queue. Run inbox triage or check a proposed interview time.')}</div>`}
function activity(){return heading('A clear trail of every step.','See what changed, when it happened, and which decisions were yours.',btn('Export history','export-history','','download'))+`<section class="card">${state.activity.map(a=>`<div class="audit-item"><span class="dot"></span><div><p>${esc(a.text)}</p><small>${full(a.at)} · ${esc(a.kind)}</small></div></div>`).join('')||empty('Your activity will appear here as you use the app.')}</section><div class="notice">This is a local activity history, not a tamper-proof audit log. Export a backup to keep a copy.</div>`}
function field(label,name,value='',type='text',hint='',wide=false){return `<label class="field ${wide?'wide':''}"><span>${label}</span>${type==='textarea'?`<textarea name="${name}" rows="${name==='experience'?6:3}">${esc(value)}</textarea>`:`<input name="${name}" type="${type}" value="${esc(value)}" ${['company','role','title','start','end','due','from','subject'].includes(name)?'required':''}>`}${hint?`<small>${hint}</small>`:''}</label>`}
function profile(){const p=state.profile,filled=['name','email','education','target','skills','experience','about'].filter(k=>p[k]?.trim()).length;return heading('The assistant should know you.','Your saved facts shape your drafts and interview preparation. Unknown details stay blank.',btn('Load RESUME FILLER profile','load-filler','','link')+btn('Import profile','import-profile','','download')+btn('Export profile','export-profile','','external'))+`<div class="profile-banner"><span class="avatar" style="height:48px;width:48px">${p.name?esc(initials(p.name)):icon('user')}</span><div style="flex:1"><h2>${p.name?esc(p.name):'Let’s start with your story.'}</h2><p>${filled} of 7 core sections filled · ${mode==='demo'?'Demo profile is separate from your real workspace.':'Saved in this browser, used across this workspace.'}</p><div class="progress"><div style="width:${filled/7*100}%"></div></div></div>${badge('You control every fact','green')}</div><form id="profile-form"><div class="two-col"><section class="card"><h2 style="margin-bottom:20px">The essentials</h2><div class="form-grid">${field('Your name','name',p.name,'text','Used in draft signatures. Never inferred.')}${field('Email address','email',p.email,'email','For your profile only. Does not connect Gmail.')}${field('Education','education',p.education,'text','Context supplied in this chat; edit if needed.')}${field('Location / preferred cities','location',p.location,'text','No city preference assumed.')}${field('Roles you’re looking for','target',p.target,'text','Example: brand, social media, growth marketing.',true)}${field('Skills you can support','skills',p.skills,'textarea','Separate with commas. Include only skills you actually have.',true)}</div></section><section class="card"><h2 style="margin-bottom:20px">What makes you, you</h2>${field('A short introduction','about',p.about,'textarea','What interests you? What kind of work do you want to do?')}${field('Experience, projects & achievements','experience',p.experience,'textarea','Paste relevant résumé text. Include your role, contribution and actual results.')}<div class="notice">AUTO WORK never invents your grades, job history, work authorization, availability, identity or achievements. Confirm factual answers yourself.</div></section><section class="card full-width"><h2 style="margin-bottom:18px">RESUME FILLER bridge</h2>${field('Existing project URL (optional)','fillerURL',p.fillerURL,'url','Link to your existing project. This does not grant extension access or automatically update its saved profile.')}<p class="tiny">Export your profile as JSON, then import it into a compatible RESUME FILLER build. Your current extension may need its import handler added; a bridge contract is included in the code package.</p><div class="button-row">${btn('Save my profile','submit-profile','primary','check')}${p.fillerURL?`<a class="btn" href="${esc(safeURL(p.fillerURL))}" target="_blank" rel="noopener noreferrer">Open RESUME FILLER ${icon('external')}</a>`:''}</div></section></div></form>`}
function settings(){return heading('Connected on your terms.','Start local. Connect only what you need, when you’re ready.')+`<div class="two-col"><section class="card"><h2 style="margin-bottom:20px">Your connections</h2><div class="integration"><div class="integration-head"><span class="integration-logo" style="color:#ce6550">M</span><h3>Gmail</h3>${badge(backend?.google?'Connected · read only':backend?.gmailStatus==='reauthentication_required'?'Authorization required':'Not connected',backend?.google?'green':'')}</div><p>Import up to 20 recent career-related messages on demand. ${backend?.hosted?'Uses your own connected Gmail through ChatGPT.':'The local server supports Google OAuth.'} ${backend?.account?esc(backend.account.email):''} Sending, deleting and marking mail read are unavailable.</p><div class="button-row">${btn('Connect Google','connect-google','','link')}${btn('Sync Gmail','sync-gmail','','refresh',backend?.google&&mode==='workspace'?'':'disabled')}</div></div><div class="integration"><div class="integration-head"><span class="integration-logo" style="color:#6285bd">31</span><h3>Google Calendar</h3>${badge(backend?.google&&!backend?.hosted?'Read-only session':'Not connected',backend?.google&&!backend?.hosted?'green':'')}</div><p>Import busy events from your primary calendar for the next 30 days. Conflict checks cover imported events only. External writes are unavailable.</p><div class="button-row">${btn('Sync calendar','sync-calendar','','refresh',backend?.google&&!backend?.hosted&&mode==='workspace'?'':'disabled')}</div></div><div class="integration"><div class="integration-head"><span class="integration-logo" style="color:#7c789b">R</span><h3>RESUME FILLER</h3>${badge('File bridge','purple')}</div><p>Share saved profile facts and import application records as JSON. Direct browser-extension access is not configured.</p><div class="button-row">${btn('Export my profile','export-profile','','download')}${btn('Import applications','import-jobs','','plus')}</div></div><div class="integration"><div class="integration-head"><span class="integration-logo">✳</span><h3>AI & live research</h3>${badge('Not configured','amber')}</div><p>The current app uses local triage rules and profile-based preparation templates. No model requests, API keys, automatic web research or paid AI usage are active. Activation design is documented in the code package.</p></div>${backend?.google&&!backend.hosted?btn('Disconnect Google session','disconnect-google','danger'):''}</section><div class="stack"><section class="card"><h2>Automation & permissions</h2><div class="toggle-row"><div><h3>Triage while the app is open</h3><p>Every minute, classify newly imported messages and queue reply drafts locally.</p></div><button class="toggle ${state.settings.autoTriage?'on':''}" role="switch" aria-checked="${state.settings.autoTriage}" data-action="toggle-triage" aria-label="Automatic local triage"></button></div><div class="toggle-row"><div><h3>Email sending</h3><p>No send endpoint or permission exists.</p></div>${badge('Unavailable')}</div><div class="toggle-row"><div><h3>Calendar changes</h3><p>Download .ics files for manual import only.</p></div>${badge('Manual only')}</div><div class="toggle-row"><div><h3>Background operation</h3><p>Browser workflows stop when closed. A separate local inbox worker is included in the package; it must be scheduled explicitly.</p></div>${badge('Not scheduled','amber')}</div><label class="field" style="margin-top:18px"><span>Conflict buffer in minutes</span><select id="buffer">${[0,5,10,15,30,60].map(n=>`<option ${n===state.settings.buffer?'selected':''}>${n}</option>`).join('')}</select></label><div class="notice">Reminders appear inside this app while it is open. There are no push, email or desktop notifications.</div></section><section class="card"><h2>Your data, your choice</h2><p class="body-text">Your profile, messages and notes are stored in this browser’s local storage. They are not encrypted at rest. Use a private device and export a backup before clearing browser data. ${backend?.hosted?'Gmail credentials stay with the connected-app service; this dashboard never receives your tokens.':'Google tokens stay in the local server’s memory and disappear on disconnect or restart.'}</p><div class="button-row">${btn('Export backup','export','','download')}${btn('Restore backup','restore','','refresh')}${btn(mode==='demo'?'Open my workspace':'Explore demo','switch-mode','','arrow')}</div><div class="danger-zone">${btn('Clear this workspace','clear-data','danger','trash')}</div></section></div></div>`}
function modal(title,content,onSubmit=null,label='Save'){const d=$('#dialog');d.innerHTML=`<div class="modal-top"><h2 id="dialog-title">${esc(title)}</h2><button data-action="close-modal" aria-label="Close dialog">×</button></div>${onSubmit?'<form id="modal-form">':''}${content}${onSubmit?`<div class="modal-footer"><button type="button" class="btn" data-action="close-modal">Cancel</button><button type="submit" class="btn primary">${label}</button></div></form>`:''}`;if(!d.open)d.showModal();if(onSubmit)$('#modal-form').onsubmit=e=>{e.preventDefault();try{onSubmit(Object.fromEntries(new FormData(e.target)),e.target)}catch(err){toast(err.message)}}}
function close(){if($('#dialog').open)$('#dialog').close()}
function appOptions(value=''){return `<label class="field"><span>Linked application</span><select name="appId"><option value="">Not linked</option>${state.apps.map(a=>`<option value="${a.id}" ${a.id===value?'selected':''}>${esc(a.company)} · ${esc(a.role)}</option>`).join('')}</select></label>`}
function editApp(id='',stage='Saved'){let a=appFor(id)||{company:'',role:'',stage,description:'',deadline:'',url:'',notes:''};modal(id?'Application details':'Add an opportunity',`<div class="form-grid">${field('Company','company',a.company)}${field('Role','role',a.role)}<label class="field"><span>Stage</span><select name="stage">${STAGES.map(s=>`<option ${s===a.stage?'selected':''}>${s}</option>`).join('')}</select></label>${field('Follow-up date','deadline',a.deadline?a.deadline.slice(0,10):'','date')}${field('Job posting URL','url',a.url,'url','',true)}${field('Job description','description',a.description,'textarea','Used to personalize interview preparation.',true)}${field('Your notes','notes',a.notes,'textarea','',true)}</div>`,f=>{if(f.url&&!safeURL(f.url))throw new Error('Enter a valid http or https URL.');if(!f.company.trim()||!f.role.trim())throw new Error('Add a company and role.');const data={...f,company:f.company.trim(),role:f.role.trim(),deadline:f.deadline?new Date(f.deadline+'T12:00:00').toISOString():''};if(id)Object.assign(a,data);else state.apps.push({...data,id:uid(),color:['peach','green','lavender','yellow'][state.apps.length%4]});log(`${id?'Updated':'Added'} application: ${f.company} · ${f.role}.`);close();save('Application saved.');})}
function importMessage(){modal('Import a message',`<p class="tiny">Paste a message to triage locally. Check the sender independently. Imported text is treated as content, never as instructions.</p>${field('Sender','from','','text')}${field('Subject','subject','','text')}${field('Message text','body','','textarea')}${appOptions()}`,f=>{state.messages.unshift({...f,id:uid(),received:new Date().toISOString(),processed:false,category:'Unprocessed'});log(`Imported message: ${f.subject}.`);if(state.settings.autoTriage)triage(state);close();save('Message imported. Run triage to classify it.')},'Import message')}
function messageDetail(id){const m=state.messages.find(x=>x.id===id);modal(m.subject,`<p class="tiny">From ${esc(m.from)} · ${full(m.received)}</p>${badge(m.category||'Unprocessed',m.category==='Interview'?'purple':'')}<div class="notice">${esc(m.reason||'Run triage to classify this message.')}<br>Classification is a suggestion. You can correct it below.</div>${m.previewOnly?`<div class="notice amber">Gmail excerpt only. Read the full message before treating this as an interview invitation.</div>${btn('Read full email','read-full','','mail',`data-id="${m.id}"`)}`:''}<p class="body-text">${esc(m.body)}</p>${m.source==='google'?`<a class="btn" href="https://mail.google.com/mail/u/0/#all/${esc(m.gmailId||m.id.replace('gmail-',''))}" target="_blank" rel="noopener noreferrer">Open in Gmail ${icon('external')}</a>`:''}<form id="message-form"><label class="field"><span>Category</span><select name="category">${['Interview','Application','Offer','Update','Other'].map(c=>`<option ${m.category===c?'selected':''}>${c}</option>`).join('')}</select></label>${appOptions(m.appId)}<div class="button-row"><button class="btn primary" type="submit">Save category & link</button>${btn('Create reply draft','draft-message','','mail',`type="button" data-id="${id}"`)}${btn('Check interview time','schedule','','calendar','type="button"')}</div></form>`);$('#message-form').onsubmit=e=>{e.preventDefault();Object.assign(m,Object.fromEntries(new FormData(e.target)),{processed:true,reason:'Manually reviewed by you.'});log(`Reviewed message category: ${m.subject}.`);close();save('Message updated.')};}
function schedule(){const next=upcoming().find(e=>e.type==='Interview');let start=next?.start||day(1,14),end=next?.end||new Date(Date.parse(start)+30*60000).toISOString();modal('Check an interview time',`<p class="tiny">Enter the exact time and time zone confirmed by the recruiter. Times entered here use <b>${new Intl.DateTimeFormat().resolvedOptions().timeZone}</b>.</p>${appOptions(selectedApp)}${field('Meeting title','title','Interview')}${field('Start','start',localInput(start),'datetime-local')}${field('End','end',localInput(end),'datetime-local')}<div class="notice">Only local and imported calendar events are checked. There may be other commitments outside this workspace.</div>`,f=>{const start=new Date(f.start).toISOString(),end=new Date(f.end).toISOString();const hits=conflicts(start,end,state.events,state.settings.buffer);const alts=hits.length?alternatives(start,state.events,(Date.parse(end)-Date.parse(start))/60000,state.settings.buffer):[];modal(hits.length?'This time needs a second look.':'This time looks clear locally.',`<div class="notice ${hits.length?'amber':''}">${hits.length?`${hits.length} conflict${hits.length>1?'s':''}, including ${state.settings.buffer} minutes of buffer.`:'No overlap found in your saved events.'}</div>${hits.map(e=>`<p class="body-text"><b>${esc(e.title)}</b><br>${full(e.start)} – ${tm(e.end)}</p>`).join('')}${alts.length?`<h3>Possible alternatives</h3>${alts.map((a,i)=>btn(full(a.start),'use-alternative','', 'clock',`data-start="${a.start}" data-end="${a.end}" data-title="${esc(f.title)}" data-app="${f.appId}"`)).join(' ')}<p class="tiny">Alternatives use weekdays between 9 AM and 5 PM in your browser time zone.</p>`:''}<div class="button-row">${btn(hits.length?'Queue with conflict noted':'Queue scheduling plan','queue-schedule',hits.length?'':'primary','shield',`data-start="${start}" data-end="${end}" data-title="${esc(f.title)}" data-app="${f.appId}" data-hits="${hits.length}"`)}</div><p class="tiny">Queueing creates a local plan for review. No invitation is sent.</p>`);},'Check conflicts')}
function addEvent(){modal('Add a local busy block',`${field('Title','title','')}${field('Start','start',localInput(day(1,10)),'datetime-local')}${field('End','end',localInput(day(1,11)),'datetime-local')}<label class="field"><span>Type</span><select name="type"><option>Personal</option><option>Class</option><option>Interview</option><option>Preparation</option></select></label>${appOptions()}`,f=>{const start=new Date(f.start).toISOString(),end=new Date(f.end).toISOString();conflicts(start,end,[]);state.events.push({...f,id:uid(),start,end,busy:true});log(`Added local calendar block: ${f.title}.`);close();save('Local busy block saved. Google Calendar was not changed.')})}
function addReminder(){modal('A little nudge for later',`${field('Reminder','title','')}${field('When','due',localInput(day(1,9)),'datetime-local')}${appOptions(selectedApp)}`,f=>{state.reminders.push({...f,id:uid(),due:new Date(f.due).toISOString(),done:false});log(`Added reminder: ${f.title}.`);close();save('Reminder saved. It will appear in-app while open.')})}
function addSource(){if(!selectedApp)return toast('Add an application first.');modal('Add company research',`${field('Source title','title','')}${field('Source URL','url','','url','Link to the original company page, job posting or announcement.')}<label class="field"><span>How should this note be treated?</span><select name="type"><option>Fact</option><option>Hypothesis</option></select></label>${field('What did you learn?','note','','textarea','Keep sourced facts separate from assumptions.')}`,f=>{if(!safeURL(f.url))throw new Error('Add a valid http or https source URL.');state.sources.push({...f,id:uid(),appId:selectedApp,added:new Date().toISOString()});log(`Added research source: ${f.title}.`);close();save('Source saved. Verify the note against the original page.')})}
function reviewApproval(id){const a=state.approvals.find(x=>x.id===id);if(a.status!=='pending')return toast('This item has already been reviewed.');modal('Review before your green light',a.type==='reply'?`${field('Reply draft','body',a.body,'textarea','No email will be sent. Replace any placeholders before approving.')}<div class="notice">Approval marks this draft as ready for you to copy. Sending is unavailable.</div>`:`<p class="body-text">${esc(a.title)}<br>${full(a.start)} – ${tm(a.end)}</p><div class="notice amber">Availability will be checked again. Approval does not create a Google Calendar event.</div><label class="check-line"><input type="checkbox" name="confirmed" required> I confirmed this time, duration and time zone with the recruiter.</label>`,f=>{if(a.type==='reply'){if(!f.body.trim()||/\[[^\]]+\]/.test(f.body))throw new Error('Replace bracketed placeholders and add your final wording.');a.body=f.body}else{const hits=conflicts(a.start,a.end,state.events,state.settings.buffer);if(hits.length)throw new Error('This time conflicts with a saved event. Reject the plan and choose another time.');}a.status='approved';a.approvedAt=new Date().toISOString();if(a.type==='schedule'){state.events.push({id:'plan-'+a.id,title:a.title+' · local plan',start:a.start,end:a.end,type:'Interview',appId:a.appId,approvalId:a.id,busy:true});const linked=appFor(a.appId);if(linked)linked.stage='Interview';for(const hours of [24,1]){const due=new Date(Date.parse(a.start)-hours*3600000);if(+due>Date.now())state.reminders.push({id:uid(),title:(hours===24?'Prepare for ':'Interview in 1 hour: ')+a.title,due:due.toISOString(),done:false,appId:a.appId})}}log(`Approved local ${a.type==='reply'?'draft':'scheduling plan'}: ${a.title}. No external action performed.`,'user decision');close();save(a.type==='schedule'?'Local hold and future prep reminders saved. Export when ready.':'Draft approved locally. Copy it when ready.')},'Approve locally')}
function profilePayload(){return {schemaVersion:1,source:'AUTO WORK',exportedAt:new Date().toISOString(),profile:state.profile}}
async function importFile(kind){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{const file=input.files[0];if(!file)return;if(file.size>3000000)throw new Error('Please choose a JSON file smaller than 3 MB.');const raw=JSON.parse(await file.text());if(kind==='profile'){const p=profileImport(raw);modal('Review imported profile',`<p class="tiny">These facts will replace your current profile. Check them before saving.</p>${Object.entries(p).filter(([k,v])=>v).map(([k,v])=>`<p class="body-text"><b>${esc(k)}</b><br>${esc(v)}</p>`).join('')}`,()=>{state.profile=p;log('Imported a saved profile; user reviewed fields.');close();save('Profile imported.')},'Use this profile')}else if(kind==='jobs'){const rows=Array.isArray(raw)?raw:raw.applications;if(!Array.isArray(rows)||rows.length>1000)throw new Error('Expected an applications array, up to 1,000 items.');const jobs=rows.map(x=>{if(!x||typeof x.company!=='string'||typeof x.role!=='string'||!x.company.trim()||!x.role.trim())throw new Error('Every application needs a company and role.');return {id:uid(),company:x.company.slice(0,300),role:x.role.slice(0,300),stage:STAGES.includes(x.stage)?x.stage:'Saved',description:String(x.description||'').slice(0,20000),url:safeURL(x.url||''),notes:String(x.notes||'').slice(0,10000),deadline:'',color:'green'}});let added=0;for(const a of jobs)if(!state.apps.some(b=>b.company.toLowerCase()===a.company.toLowerCase()&&b.role.toLowerCase()===a.role.toLowerCase())){state.apps.push(a);added++}log(`Imported ${added} applications from JSON; exact company/role duplicates skipped.`);save(`${added} applications imported.`)}else{validateBackup(raw);modal('Restore this workspace?',`<p class="body-text">This replaces the current ${mode} workspace with ${raw.apps.length} applications and ${raw.messages.length} messages. Export your current data first if you want to keep it.</p>`,()=>{state=raw;state.demo=mode==='demo';log('Restored workspace from a user-selected backup.');selectedApp=state.apps[0]?.id||'';close();save('Backup restored.')},'Replace workspace')}}catch(e){toast('Import failed: '+e.message)}};input.click()}
function validateBackup(s){if(!s||s.version!==1)throw new Error('Unsupported backup format.');validateProfile(s.profile||{});for(const k of ['apps','messages','events','approvals','reminders','sources','activity']){if(!Array.isArray(s[k])||s[k].length>10000)throw new Error('Invalid '+k);for(const r of s[k]){if(!r||typeof r.id!=='string'||r.id.length>100||!/^[a-zA-Z0-9_-]+$/.test(r.id))throw new Error('Invalid record ID.')}}for(const e of s.events)conflicts(e.start,e.end,[]);for(const a of s.apps)if(typeof a.company!=='string'||typeof a.role!=='string'||!STAGES.includes(a.stage))throw new Error('Invalid application.');if(!s.settings||![0,5,10,15,30,60].includes(s.settings.buffer)||typeof s.settings.autoTriage!=='boolean')throw new Error('Invalid settings.');if(!s.notes||Array.isArray(s.notes)||typeof s.notes!=='object')throw new Error('Invalid notes.');for(const m of s.messages)if(typeof m.subject!=='string'||typeof m.from!=='string'||typeof m.body!=='string')throw new Error('Invalid message.');for(const a of s.approvals){if(!['reply','schedule'].includes(a.type)||!['pending','approved','rejected'].includes(a.status))throw new Error('Invalid approval.');if(a.type==='schedule')conflicts(a.start,a.end,[]);}return true}
async function api(path,body){const r=await fetch('/api/'+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json','X-AW-CSRF':backend?.csrf||''}:{},body:body?JSON.stringify(body):undefined,cache:'no-store'});let x;try{x=await r.json()}catch{throw new Error('The connection service did not respond. Refresh this page and try again.')}if(!r.ok||(x.status&&x.status!=='success')){const error=new Error(x.error||x.message||'Connection failed');error.status=x.status;error.reconnect=x.chatGPTSignInPath;error.retryAfterMs=x.retryAfterMs;if(x.retryAfterMs)gmailRetryAfter=Date.now()+x.retryAfterMs;throw error}return x}
async function backendStatus(){try{backend=await api('status');if(backend.hosted){try{const result=await api('gmail/account',{});backend.google=true;backend.account=result.account;backend.gmailStatus='connected';if(mode==='workspace'&&!state.profile.name&&!state.profile.email){state.profile.name=result.account.name;state.profile.email=result.account.email;persist()}}catch(e){backend.google=false;backend.gmailStatus=e.status;backend.gmailReconnect=e.reconnect;backend.gmailError=e.message}}}catch{backend=null}render()}
async function syncGoogle(type){if(mode!=='workspace')return toast('Open your personal workspace before importing real data.');if(gmailBusy)return;if(Date.now()<gmailRetryAfter)return toast('Gmail requested a pause. Try again after '+new Date(gmailRetryAfter).toLocaleTimeString());gmailBusy=true;render();toast('Reading Google '+(type==='gmail'?'messages…':'Calendar…'));try{const r=await api('sync/'+type,{});let count=0;if(type==='gmail'){for(const m of r.messages){if(!state.messages.some(x=>x.id===m.id)){state.messages.unshift(m);count++}}state.messages.sort((a,b)=>Date.parse(b.received)-Date.parse(a.received));state.lastGmailSync=new Date().toISOString();gmailError='';if(backend)backend.google=true}else{for(const e of r.events){const old=state.events.find(x=>x.id===e.id);if(old)Object.assign(old,e);else{state.events.push(e);count++}}const keep=new Set(r.events.map(e=>e.id));state.events=state.events.filter(e=>e.source!=='google'||keep.has(e.id));count=r.events.length}log(`Google ${type==='gmail'?'Gmail':'Calendar'} read-only sync: ${count} ${type==='gmail'?'new messages':'events refreshed'}.`,'integration');if(state.settings.autoTriage)triage(state);save(`Synced ${count} ${type==='gmail'?'new messages':'events'}. ${r.truncated?'More matching records exist; this refresh shows the first batch.':''}`)}catch(e){gmailError=e.message;render();toast(e.message);if(e.status==='reauthentication_required'&&e.reconnect)modal('Authorize Gmail for AUTO WORK',`<p class="body-text">Your ChatGPT Gmail connection needs authorization for this site. Continue with ChatGPT, then return and refresh Gmail.</p><a class="btn primary" href="${esc(e.reconnect)}" target="_top">Authorize Gmail</a>`)}finally{gmailBusy=false;render()}}

