document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el)return;const fn=actions[el.dataset.action];if(fn){e.preventDefault();try{await fn(el)}catch(err){toast(err.message||'Something went wrong. Your data is still saved.')}}});
document.addEventListener('keydown',e=>{const el=e.target.closest('.job-card');if(el&&(e.key==='Enter'||e.key===' ')){e.preventDefault();editApp(el.dataset.id)}});
document.addEventListener('submit',e=>{if(e.target.id==='profile-form'){e.preventDefault();try{state.profile=validateProfile(Object.fromEntries(new FormData(e.target)));log('Updated saved personal profile. Preparation now uses these facts.','user decision');save('Your profile is saved. Preparation and new drafts will use it.')}catch(err){toast(err.message)}}});
document.addEventListener('change',e=>{if(e.target.id==='prep-app'){selectedApp=e.target.value;render()}if(e.target.id==='buffer'){state.settings.buffer=Number(e.target.value);log(`Set scheduling buffer to ${state.settings.buffer} minutes.`);save('Conflict buffer updated.')}});
document.addEventListener('input',e=>{if(e.target.id==='inbox-search'){const position=e.target.selectionStart;search=e.target.value;render();$('#inbox-search').focus();$('#inbox-search').setSelectionRange(position,position)}});
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close()}});
let seenReminders=new Set();setInterval(()=>{if(state.settings.autoTriage){const n=triage(state);if(n){log(`Automatic local triage classified ${n} new messages.`,'local rules');save()}}const due=state.reminders.find(r=>!r.done&&Date.parse(r.due)<=Date.now()&&!seenReminders.has(r.id));if(due){seenReminders.add(due.id);toast('Reminder: '+due.title)}},60000);
